local ForgeRakeMaker = {}
local PRODUCTS = {
    iron_forgerake = { name = "Železni grebalec za ognjiscce", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni grebalec za ognjiscce za kovace." },
    bronze_forgerake = { name = "Bronast grebalec za ognjiscce", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast grebalec za ognjiscce za kovace." },
    silver_forgerake = { name = "Srebrn grebalec za ognjiscce", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn grebalec za ognjiscce za kovace." },
    gilded_forgerake = { name = "Pozlačen grebalec za ognjiscce", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen grebalec za ognjiscce za kovace." },
    jewel_set_forgerake = { name = "Draguljast grebalec za ognjiscce", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast grebalec za ognjiscce za kovace." },
    royal_sovereign_forgerake = { name = "Kraljevski suveren grebalec za ognjiscce", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren grebalec za ognjiscce z biseri za krono." },
}
local BUILDINGS = {
    forgerake_workshop = { name = "Forgerake delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    forgerake_house = { name = "Forgerake hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_forgerake_atelier = { name = "Mojstrski forgerake atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_forgerake_palace = { name = "Suverena forgerake palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ForgeRakeMaker.ironStock = 16; ForgeRakeMaker.bronzeStock = 14; ForgeRakeMaker.woodStock = 10; ForgeRakeMaker.leatherStock = 8; ForgeRakeMaker.silverStock = 8; ForgeRakeMaker.goldStock = 6; ForgeRakeMaker.jewelStock = 4; ForgeRakeMaker.pearlStock = 4
ForgeRakeMaker.productStock = {}; ForgeRakeMaker.buildings = {}; ForgeRakeMaker.maker = nil; ForgeRakeMaker.activeMaking = {}; ForgeRakeMaker.totalProducts = 0; ForgeRakeMaker.dayTimer = 0
function ForgeRakeMaker.init() ForgeRakeMaker.ironStock=16; ForgeRakeMaker.bronzeStock=14; ForgeRakeMaker.woodStock=10; ForgeRakeMaker.leatherStock=8; ForgeRakeMaker.silverStock=8; ForgeRakeMaker.goldStock=6; ForgeRakeMaker.jewelStock=4; ForgeRakeMaker.pearlStock=4; ForgeRakeMaker.productStock={}; ForgeRakeMaker.buildings={}; ForgeRakeMaker.maker=nil; ForgeRakeMaker.activeMaking={}; ForgeRakeMaker.totalProducts=0; ForgeRakeMaker.dayTimer=0; print("[ForgeRakeMaker] Royal Forge Rake Maker System initialized (6 products, 4 buildings)") end
function ForgeRakeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeRakeMaker.maker={name=n or ("Grebar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grebar najet: %s (spretnost: %d)",ForgeRakeMaker.maker.name,s),"success") end; return true end
function ForgeRakeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeRakeMaker.build(id) local ok,e=ForgeRakeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeRakeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeRakeMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeRakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeRakeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeRakeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeRakeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeRakeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeRakeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeRakeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeRakeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeRakeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeRakeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeRakeMaker.buildings==0 then return false,"Potrebna grebalna delavnica" end; if not ForgeRakeMaker.maker then return false,"Potreben grebar" end; return true end
function ForgeRakeMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeRakeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeRakeMaker.ironStock=ForgeRakeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeRakeMaker.bronzeStock=ForgeRakeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeRakeMaker.woodStock=ForgeRakeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeRakeMaker.leatherStock=ForgeRakeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeRakeMaker.silverStock=ForgeRakeMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeRakeMaker.goldStock=ForgeRakeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeRakeMaker.jewelStock=ForgeRakeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeRakeMaker.pearlStock=ForgeRakeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeRakeMaker.maker then t=math.max(1,t-math.floor(ForgeRakeMaker.maker.skill/13)) end; table.insert(ForgeRakeMaker.activeMaking,{id="forgerake_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeRakeMaker.completeMaking(m) local q=1.0+(ForgeRakeMaker.getQualityBonus()/100); if ForgeRakeMaker.maker then q=q+(ForgeRakeMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeRakeMaker.productStock[m.productType]=(ForgeRakeMaker.productStock[m.productType] or 0)+m.quantity; ForgeRakeMaker.totalProducts=ForgeRakeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeRakeMaker.maker then ForgeRakeMaker.maker.itemsMade=ForgeRakeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeRakeMaker.maker.skill=math.min(100,ForgeRakeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grebalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgerake.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function ForgeRakeMaker.update(dt) if not _G.state then return end; ForgeRakeMaker.dayTimer=ForgeRakeMaker.dayTimer+dt; if ForgeRakeMaker.dayTimer>=30 then ForgeRakeMaker.dayTimer=0; for i=#ForgeRakeMaker.activeMaking,1,-1 do local m=ForgeRakeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeRakeMaker.completeMaking(m); table.remove(ForgeRakeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeRakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeRakeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeRakeMaker.getStats() return {ironStock=ForgeRakeMaker.ironStock,bronzeStock=ForgeRakeMaker.bronzeStock,woodStock=ForgeRakeMaker.woodStock,leatherStock=ForgeRakeMaker.leatherStock,silverStock=ForgeRakeMaker.silverStock,goldStock=ForgeRakeMaker.goldStock,jewelStock=ForgeRakeMaker.jewelStock,pearlStock=ForgeRakeMaker.pearlStock,productStock=ForgeRakeMaker.productStock,numBuildings=#ForgeRakeMaker.buildings,hasMaker=ForgeRakeMaker.maker~=nil,makerName=ForgeRakeMaker.maker and ForgeRakeMaker.maker.name or "—",makerSkill=ForgeRakeMaker.maker and ForgeRakeMaker.maker.skill or 0,activeMaking=#ForgeRakeMaker.activeMaking,totalProducts=ForgeRakeMaker.totalProducts} end
return ForgeRakeMaker
